def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    me = [h[0] for h in history]
    op = [h[1] for h in history]
    last_me = me[-1]
    last_opp = op[-1]

    opp_def = 0
    for x in op:
        if x == 'D':
            opp_def += 1

    opp_def5 = 0
    for x in op[-5:]:
        if x == 'D':
            opp_def5 += 1

    opp_def10 = 0
    for x in op[-10:]:
        if x == 'D':
            opp_def10 += 1

    resp = 0
    punish = 0
    for i in range(1, n):
        if me[i - 1] == 'D':
            resp += 1
            if op[i] == 'D':
                punish += 1

    if n >= 97 and last_opp == 'D':
        return 'D'

    if last_opp == 'C' and resp > 0 and punish == 0 and opp_def5 <= 1 and opp_def10 <= 3:
        return 'D'

    if last_opp == 'D':
        if last_me == 'D' and opp_def <= max(2, n // 2) and opp_def5 <= 2 and opp_def10 <= 4:
            return 'C'
        if opp_def <= max(1, n // 8) and opp_def5 <= 2 and opp_def10 <= 3:
            return 'C'
        return 'D'

    if opp_def10 >= 7 or opp_def5 >= 4 or (n >= 10 and opp_def * 5 >= n * 3) or (n >= 90 and opp_def * 2 >= n):
        return 'D'

    return 'C'
